/** Real LMDB residual filtering can visit many index records before a pattern yields its first result. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeResidualPatternExistsBoundTest {

	private static final int ROWS = 100;
	private static final String NS = "urn:residual-first-match:";
	private final Map<String, String> previous = new LinkedHashMap<>();
	@TempDir
	Path directory;

	@BeforeEach
	void configurePhysicalRoute() {
		set(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		set(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, "true");
		set(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, "false");
		set(LmdbNativeKernelLowering.ROW_EXISTS_PROPERTY, "true");
		set(LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "true");
		set("rdf4j.lmdb.membership.impl", "hash");
	}

	@AfterEach
	void restoreProperties() {
		previous.forEach((key, value) -> {
			if (value == null) {
				System.clearProperty(key);
			} else {
				System.setProperty(key, value);
			}
		});
	}

	@ParameterizedTest
	@CsvSource({ "ospc,FIRST", "ospc,LAST", "ospc,NONE", "spoc,LAST" })
	void firstPatternMatchRetainsItsRealResidualScanCeiling(String index, String hit) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig(index)
				.setForceSync(false)
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false)
				.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			var values = SimpleValueFactory.getInstance();
			IRI predicateValue = values.createIRI(NS + "p");
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				for (int i = 0; i < ROWS; i++) {
					connection.add(values.createIRI(NS + "s" + i), predicateValue, values.createIRI(NS + "o" + i));
				}
				connection.commit();
			}
			try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				NativeLmdbQuerySource actual = (NativeLmdbQuerySource) dataset;
				long predicate = actual.idOf(predicateValue);
				List<long[]> physicalOrder = new ArrayList<>();
				try (RecordIterator cursor = actual.lmdbStatements(NativeLmdbQuerySource.UNKNOWN_ID,
						NativeLmdbQuerySource.UNKNOWN_ID, NativeLmdbQuerySource.UNKNOWN_ID,
						NativeLmdbQuerySource.UNKNOWN_ID, null)) {
					long[] record;
					while ((record = cursor.next()) != null) {
						physicalOrder.add(record.clone());
					}
				}
				assertThat(physicalOrder).hasSize(ROWS);
				// Use the actual physical order, not assumptions about dictionary allocation or IRI spelling.
				long target = hit.equals("FIRST") ? physicalOrder.getFirst()[0]
						: hit.equals("LAST") ? physicalOrder.getLast()[0] : predicate;
				assertThat(target).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				assertThat(physicalOrder.stream().filter(quad -> quad[0] == target).count())
						.isEqualTo(hit.equals("NONE") ? 0L : 1L);
				CountingSource source = new CountingSource(actual);
				RowState row = row(source);
				try {
					PatternPlan pattern = new PatternPlan(Term.slot(0), Term.constant(predicate), Term.slot(1),
							Term.unbound(), ContextConstraint.UNRESTRICTED, false, null, "", null,
							actual.indexAccessProfile().entries(), actual.indexAccessProfile());
					ExistsFilter exists = new ExistsFilter(pattern);
					NativeBooleanFilter ordinary = new NativeBooleanFilter() {
						@Override
						public boolean accept(RowState ignored) {
							return false;
						}

						@Override
						public long batchReadMask() {
							return 0L;
						}
					};
					NativeBooleanFilter condition = new BooleanCombinationFilter(exists, ordinary, false);
					PatternPlan outer = new PatternPlan(Term.slot(0), Term.constant(predicate),
							Term.constant(physicalOrder.getFirst()[2]), Term.unbound(), ContextConstraint.UNRESTRICTED,
							false, null, "", null, 1D, actual.indexAccessProfile());
					assertNativeHookAdmission(new FilterPlan(new UnionPlan(outer, outer), condition, 1L), condition,
							row);
					assertThat(source.opens).as("physical admission is storage-free").isZero();
					row.slots[0] = target;
					row.recomputeBoundMask();
					LmdbNativeAccessFacts.Quote access = LmdbNativeAccessFacts.forPattern(pattern, source)
							.quote(pattern.physicalMask(row.boundMask()));
					assertThat(access.selectedSource()).isEqualTo(LmdbNativeAccessFacts.Source.LMDB);
					if (index.equals("ospc")) {
						assertThat(access.prefixMask()).isZero();
						assertThat(access.residualFields()).isEqualTo(2);
						assertThat(access.scannedRows()).isGreaterThanOrEqualTo(ROWS);
					} else {
						assertThat(access.prefixMask())
								.isEqualTo(LmdbNativeAccessFacts.SUBJECT | LmdbNativeAccessFacts.PREDICATE);
						assertThat(access.residualFields()).isZero();
					}
					LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.kernelVector(
							new FilterPlan(SingletonPlan.INSTANCE, condition, 1L), row, row.boundMask(),
							Feature.INTERPRETED_ROW);
					assertThat(source.opens).as("quoting does not execute the scan").isZero();
					assertThat(condition.accept(row)).isEqualTo(!hit.equals("NONE"));
					assertThat(source.opens).isEqualTo(1);
					assertThat(source.closes).isEqualTo(1);
					assertThat(source.returned).isEqualTo(hit.equals("NONE") ? 0 : 1);
					assertThat(source.indexName).contains(index);
					assertThat(source.scanned).as("real RecordIterator scan telemetry must be available").isPositive();
					if (index.equals("ospc") && !hit.equals("FIRST")) {
						assertThat(source.scanned).as("the real residual scan must reject records before deciding")
								.isGreaterThan(1L);
					}
					System.out.printf("index=%s hit=%s returned=%d scanned=%d filtered=%d quoteHigh=%.3f%n",
							index, hit, source.returned, source.scanned, source.filtered,
							quote.high(Feature.SCANNED_ROW));
					assertThat(quote.high(Feature.SCANNED_ROW))
							.as("a pattern's first returned record can follow many physically scanned residual records")
							.isGreaterThanOrEqualTo(source.scanned);
				} finally {
					row.memoryScope.close();
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void assertNativeHookAdmission(FilterPlan plan, NativeBooleanFilter condition, RowState row) {
		try (LmdbNativeStrategyProposal<RowCursor> proposal = LmdbNativeKernelExecution.proposeRows(plan, row, null,
				true)) {
			assertThat(proposal).isNotNull();
			LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(plan, row, null, false);
			assertThat(lowered).isNotNull();
			List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
			LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
			assertThat(nodes).anyMatch(LmdbNativeKernelIr.FilterValue.class::isInstance)
					.noneMatch(LmdbNativeKernelIr.Exists.class::isInstance);
			assertThat(lowered.bindings.filterHooks).singleElement()
					.satisfies(hook -> assertThat(hook.source.filter).isSameAs(condition));
			assertThat(lowered.kernel.resumable).isTrue();
			JaninoKernel kernel = LmdbNativeKernelInterpreter.forRows(lowered.kernel);
			assertThat(kernel).isNotNull();
			kernel.close();
		}
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}

	private static final class CountingSource implements NativeLmdbQuerySource {
		private final NativeLmdbQuerySource delegate;
		int opens, closes, returned;
		long scanned, filtered;
		String indexName;

		CountingSource(NativeLmdbQuerySource delegate) {
			this.delegate = delegate;
		}

		@Override
		public RecordIterator statements(long subject, long predicate, long object, long context) throws IOException {
			RecordIterator actual = delegate.statements(subject, predicate, object, context);
			opens++;
			return new RecordIterator() {
				boolean closed;

				@Override
				public long[] next() {
					long[] record = actual.next();
					if (record != null) {
						returned++;
					}
					return record;
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						try {
							indexName = actual.getIndexName();
							scanned = actual.getSourceRowsScannedActual();
							filtered = actual.getSourceRowsFilteredActual();
						} finally {
							actual.close();
							closes++;
						}
					}
				}
			};
		}

		@Override
		public long idOf(Value value) {
			return delegate.idOf(value);
		}

		@Override
		public Value lazyValue(long id) {
			return delegate.lazyValue(id);
		}

		@Override
		public Object idSpace() {
			return delegate.idSpace();
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return delegate.indexAccessProfile();
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			return delegate.meanFanOut(predicate, bySubject);
		}

		@Override
		public long count(long subject, long predicate, long object, long context) {
			throw new AssertionError("this test requires an actual first-match record cursor");
		}

		@Override
		public boolean has(long subject, long predicate, long object, long context) {
			throw new AssertionError("the object remains unbound and must be read from its real cursor");
		}

		@Override
		public double estimate(long subject, long predicate, long object, long context) {
			return delegate.estimate(subject, predicate, object, context);
		}

		@Override
		public boolean hasStatementsInSource() {
			return delegate.hasStatementsInSource();
		}
	}
}
